  [260822] = { "所持している、爆発を伴わないSAF-TまたはEZ-Throブランドの装置のチャージを$N1回復します。爆発物に使うのはまったくUnsafeです。", 0x848cf013, "u" },
  [260823] = { "次元の壁を引き裂き、Mount HyjalのKaylaena's Workshopへ転送します。ゴブリンとノームの工学をこのように無謀に組み合わせているため、技術的な問題が起こる可能性が高くなっています。\nゴブリンとノームの工学技術を危険なまでに混ぜ合わせた品です。", 0xa3c2df84, "u" },
  [260824] = { "対象を$D1の間ニワトリに変えます。まあ、変成術の極性が逆転していなければの話ですが……", 0x4ecdd5b2, "u" },
  [260825] = { "進行方向を操りながら、$D1の間、空中を滑空して降下します。", 0x0e9703cc, "u" },
  [260827] = { "最大$D1の間、使用者をステルスフィールドで包みます。戦闘中は使用できません。移動した後もフィールドは最大$N2秒間持続します。\n本物の秘密諜報員が使っているものです。", 0xfc7d7a88, "u" },
  [260828] = { "ジェットを起動し、最大$D1の間、移動速度を最大$N1%上昇させます。\nSAF-Tでロケットのように安全な場所へ。", 0x24b3dfe7, "u" },
  [260829] = { "自分と近くにいる敵の対象との間の磁場を乱し、両者を吹き飛ばします。\r\n\n自分より最大$N1レベル上の対象にのみ効果があります。移動させられない対象もいます。同じ対象がこの効果を受けられるのは$D1に一度だけです。\nEZ-Thro社は、磁石のせいでグレネードが投げられなくなっても責任を負いません。", 0x7c2a433a, "u" },
